import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.animationEffects().getAnimationEffects();
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("animation_effects");
Map<?, ?> preloaderDesign = (Map<?, ?>) settings.get("preloader_design");
Map<?, ?> pageTransition = (Map<?, ?>) settings.get("page_transition");
System.out.println(preloaderDesign.get("enable_preloader") + " " + preloaderDesign.get("preloader_preset"));
System.out.println(pageTransition.get("page_transition_animation_type"));

